mapper.select:
SELECT a.ApptID as apptId, a.PetID as petId, p.PetName as petName, p.Breed as breed, p.Gender as gender, p.BirthDate as birthDate, p.VaccineStatus as vaccineStatus, p.Remarks as remarks, p.AllergyDrug as allergyDrug, p.MedicalHistory as medicalHistory, a.UserID as userId, u.UserName as userName, u.Phone as userPhone, a.StoreID as storeId, s.StoreName as storeName, s.StoreAddress as storeAddress, s.StorePhone as storePhone, a.EmpID as empId, a.ApptTime as apptTime, a.ApptStatus as apptStatus, a.DiagnoseStatus as diagnoseStatus, a.DiagnoseDesc as diagnoseDesc, e.EmpName as empName, e.Position as empPosition, a.CreateTime as createTime FROM appointment a LEFT JOIN pet p ON a.PetID = p.PetID LEFT JOIN user u ON a.UserID = u.UserID LEFT JOIN store s ON a.StoreID = s.StoreID LEFT JOIN employee e ON a.EmpID = e.EmpID WHERE a.DiagnoseStatus IN ('待诊断') AND a.ApptStatus NOT IN ('已取消', '已拒绝')
AND a.StoreID = #{storeId}
AND ( p.PetName LIKE CONCAT('%', #{keyword}, '%') OR u.Phone LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY a.ApptTime ASC LIMIT #{pageSize} OFFSET #{offset}
